def _rel_tuple(rel):
    if isinstance(rel, dict):
        return (rel["x1"], rel["y1"], rel["x2"], rel["y2"])
    return (rel[0], rel[1], rel[2], rel[3])


def match_struct_lines(n2_lines, n4_lines):
    n2s = [L for L in n2_lines if L["family"] in ("Painéis", "SARR")]
    pool = [dict(L, _used=False) for L in n4_lines if L["family"] in ("Painéis", "SARR")]
    out = []
    for L in n2s:
        target = _rel_tuple(L["rel"])
        best_i, best_d = None, 1e18
        for i, s in enumerate(pool):
            if s["_used"] or s["family"] != L["family"]:
                continue
            t = _rel_tuple(s["rel"])
            d = sum(abs(target[k] - t[k]) for k in range(4)) / 4.0
            if d < best_d:
                best_d, best_i = d, i
        y_min = min(target[1], target[3])
        status = "MISSING_N4"
        n4_rel = None
        if best_i is not None and best_d <= TOL_MATCH:
            status = "MATCH"
            pool[best_i]["_used"] = True
            n4_rel = list(_rel_tuple(pool[best_i]["rel"]))
        elif best_i is not None and best_d <= TOL_NEAR:
            status = "NEAR"
            pool[best_i]["_used"] = True
            n4_rel = list(_rel_tuple(pool[best_i]["rel"]))
        elif y_min < -1:
            status = "N2_VOID_JUNK_nao_deve_copiar"
        out.append(
            {
                "n2_id": L["id"],
                "family": L["family"],
                "layer": L["layer"],
                "rel": list(target),
                "orient": L["orient"],
                "length_cm": L["length_cm"],

                "interpretacao": L["interpretacao"],
                "status": status,
                "delta_avg_cm": _r(best_d, 3) if best_i is not None else None,
                "n4_rel": n4_rel,
            }
        )
    extras = []
    for s in pool:
        if s["_used"]:
            continue
        r = _rel_tuple(s["rel"])
        if max(r[1], r[3]) < -1:
            continue
        extras.append(
            {
                "family": s["family"],
                "layer": s["layer"],
                "rel": list(r),
                "orient": s["orient"],
                "length_cm": s["length_cm"],
                "status": "EXTRA_N4",
            }
        )
    return out, extras


