# -*- coding: utf-8 -*-
"""Pacote visual V301 em SVG (evidência canônica) + HTML — abre no browser.

Protocolo Arete: SVG-only como fonte visual (texto, cotas, camadas).
PNG fica opcional/legado; o HTML embute SVG.
"""
from __future__ import annotations

import io
import sqlite3
import webbrowser
from pathlib import Path

import ezdxf
from ezdxf.addons.drawing import Frontend, RenderContext
from ezdxf.addons.drawing.matplotlib import MatplotlibBackend
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt

REPO = Path(__file__).resolve().parents[3]
sys_path_repo = REPO
import sys
sys.path.insert(0, str(REPO))
from src.ui.widgets.svg_embed_utils import strip_fixed_size  # noqa: E402

OUT = REPO / "scripts/arete/relatorios/g2v/v301_arete_review"
SVG_DIR = OUT / "svg"
SVG_DIR.mkdir(parents=True, exist_ok=True)
DB = Path(r"D:/Agente-cad-PYSIDE/project_data.vision")
N4A = Path(
    r"D:/Agente-cad-PYSIDE/DADOS-OBRAS/Obra_TREINO_1/Fase-6_Execucao_CAD/n4/"
    r"LV_preview_V301_VIEW_A.dxf"
)
N4B = Path(
    r"D:/Agente-cad-PYSIDE/DADOS-OBRAS/Obra_TREINO_1/Fase-6_Execucao_CAD/n4/"
    r"LV_preview_V301_VIEW_B.dxf"
)

FACE_A = {
    "x0": 5479.891111852656,
    "y0": 8154.0,
    "w": 445.7,
    "h": 109.0,
    "pad_l": 90,
    "pad_r": 90,
    "pad_b": 90,
    "pad_t": 50,
}


def resolve_n2() -> Path:
    conn = sqlite3.connect(str(DB))
    row = conn.execute(
        "SELECT recorte_path FROM reverse_eng_recortes "
        "WHERE UPPER(elemento_id)='V301' AND UPPER(classe)='LV' "
        "ORDER BY id DESC LIMIT 1"
    ).fetchone()
    conn.close()
    p = Path(row[0])
    assert p.exists(), p
    return p


def dxf_to_svg(path: Path, limits=None, width=1600, height=700) -> str:
    dpi = 120
    doc = ezdxf.readfile(str(path))
    msp = doc.modelspace()
    with matplotlib.rc_context({"svg.fonttype": "none"}):
        fig = plt.figure(figsize=(width / dpi, height / dpi), dpi=dpi)
        ax = fig.add_axes([0.02, 0.04, 0.96, 0.90])
        ax.set_facecolor("#0b1220")
        fig.patch.set_facecolor("#0b1220")
        Frontend(RenderContext(doc), MatplotlibBackend(ax)).draw_layout(msp)
        ax.set_aspect("equal")
        if limits:
            xl, yb, xr, yt = limits
            ax.set_xlim(xl, xr)
            ax.set_ylim(yb, yt)
        ax.tick_params(colors="#64748b", labelsize=7)
        for s in ax.spines.values():
            s.set_color("#334155")
        buf = io.BytesIO()
        fig.savefig(
            buf,
            format="svg",
            dpi=dpi,
            facecolor=fig.get_facecolor(),
            bbox_inches="tight",
            pad_inches=0.12,
        )
        plt.close(fig)
    return strip_fixed_size(buf.getvalue().decode("utf-8"))


def write_svg(name: str, content: str) -> Path:
    p = SVG_DIR / name
    p.write_text(content, encoding="utf-8")
    print("SVG", p)
    return p


def build_html(n2_path: Path, cards: list[tuple[str, str, str]]) -> Path:
    """cards: (title, svg_filename, note)"""
    blocks = []
    for title, svg_name, note in cards:
        blocks.append(
            f"""
<section class="card">
  <header>
    <h2>{title}</h2>
    <code>{note}</code>
  </header>
  <div class="view">
    <object type="image/svg+xml" data="svg/{svg_name}" class="svg-obj"></object>
    <p class="hint"><a href="svg/{svg_name}" target="_blank">abrir SVG puro</a>
      · evidência canônica (não PNG)</p>
  </div>
</section>"""
        )
    html = f"""<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>V301 · Arete SVG N2×N4</title>
<style>
  :root {{
    --bg:#0b1220; --card:#111827; --line:#1f2937; --txt:#e5e7eb;
    --muted:#94a3b8; --acc:#22d3ee; --warn:#f59e0b;
  }}
  * {{ box-sizing:border-box; }}
  body {{ margin:0; font:14px/1.45 system-ui,Segoe UI,sans-serif;
    background:var(--bg); color:var(--txt); }}
  header.top {{
    position:sticky; top:0; z-index:10;
    background:rgba(11,18,32,.96); border-bottom:1px solid var(--line);
    padding:12px 18px;
  }}
  h1 {{ margin:0; font-size:18px; color:var(--acc); }}
  .meta {{ color:var(--muted); font-size:12px; margin-top:4px; }}
  main {{ padding:16px; display:grid; gap:16px; }}
  .card {{
    background:var(--card); border:1px solid var(--line); border-radius:12px;
    overflow:hidden;
  }}
  .card header {{
    padding:10px 14px; border-bottom:1px solid var(--line);
  }}
  .card h2 {{ margin:0 0 4px; font-size:15px; color:#f472b6; }}
  .card code {{ color:var(--muted); font-size:11px; word-break:break-all; }}
  .view {{ padding:10px; background:#020617; }}
  .svg-obj {{
    display:block; width:100%; min-height:420px; max-width:1600px; margin:0 auto;
    background:#0b1220; border-radius:8px;
  }}
  .hint {{ margin:8px 0 0; color:var(--muted); font-size:12px; }}
