            "N2 · recorte FULL (como CE carrega LV reverso)",
            "N2_CE_full_recorte.svg",
            "Sem cull bbox — zoom manual no CE foca V301.A",
        ),
    ]
    if N4B.exists():
        cards.append(
            ("N4 · VIEW_B (gerado)", "N4_VIEW_B.svg", str(N4B))
        )

    html = build_html(n2, cards)
