def _degrau_shoulder_y(y0, h, panels):
    """Y da base dos painéis curtos (ombro do degrau) na face."""
    degrau = [p for p in panels if _is_degrau_panel(p, h)]
    if not degrau:
        return None
    y_degrau = _panel_y_base(y0, h, degrau[0])
    if y_degrau <= y0 + 1.0:
        return None
    return y_degrau


def _degrau_zone_end_x(x0, h, panels):
    x = float(x0)
    for panel in panels:
        if not _is_degrau_panel(panel, h):
            break
        x += float(panel.get('width', 0) or 0)
    return x


def _small_panel_start_x(x0, h, panels, threshold=25.0):
    x = float(x0)
    for panel in panels:
        pw = float(panel.get('width', 0) or 0)
        if not _is_degrau_panel(panel, h) and pw < threshold:
            return x
        x += pw
    return None

